fn gcd_calc(mut m: u32, mut n: u32) -> u32 {
    // Both m and n start strictly positive as per problem statement.
    // We use the Euclidean algorithm:
    // - At each step, replace the larger number by the remainder of dividing it by the smaller.
    // - This maintains both values strictly positive until one reaches zero;
    //   however, the loop here runs while both are > 0, and when one hits zero,
    //   the other is the gcd.
    // The sum of m + n strictly decreases each iteration because remainder < divisor.
    
    while n != 0 {
        // Swap m and n so that m >= n after each iteration (optional, but often done).
        // More simply, we just use Euclid's remainder step: m = m % n; then swap.
        let r = m % n;
        m = n;
        n = r;
    }
    m
}